import { HugeiconsIcon } from "@hugeicons/react";
import CheckIcon from "@hugeicons/core-free-icons/CheckIcon";
import CopyIcon from "@hugeicons/core-free-icons/CopyIcon";

import { Button } from "@/registry/erbium/ui/button";
import { useCopyToClipboard } from "@/registry/erbium/hooks/use-copy-to-clipboard";
import { StatefulIcon } from "@/registry/erbium/ui/stateful-icon";

export default function StatefulIconDemo() {
  const { copyToClipboard, isCopied } = useCopyToClipboard({ timeout: 1200 });

  return (
    <Button
      aria-label={isCopied ? "Copied" : "Copy example text"}
      onClick={() => void copyToClipboard("Stateful icons animate between states.")}
      size="icon"
      variant="outline"
    >
      <StatefulIcon
        state={isCopied ? "success" : "idle"}
        icons={{
          idle: <HugeiconsIcon icon={CopyIcon} className="size-4" />,
          success: <HugeiconsIcon icon={CheckIcon} className="size-4" />,
        }}
      />
    </Button>
  );
}

import StatefulIconDemo from "../examples/stateful-icon-demo";

const Example = () => <StatefulIconDemo />;

export default Example;
